+  if (typeof args.cents !== 'number' || !Number.isInteger(args.cents) || args.cents <= 0) {
+    fail('cents must be an integer greater than 0');
+  }
+}
+
+export async function callTool(name, args = {}) {
+  if (name !== 'charge') {
+    fail('Unknown tool: ' + name, -32601);
+  }
+  validateCharge(args);
+
+  const { request_id } = args;
+
+  // Idempotent replay: return the exact same charge without incrementing the count.
+  if (store.has(request_id)) {
+    const existing = store.get(request_id);
+    return {
+      content: [
+        {
+          type: 'text',
+          text: JSON.stringify({ charged: existing.charged, charge_id: existing.charge_id }),
+        },
+      ],
+    };
+  }
+
+  const charge_id = 'ch' + nextId;
+  nextId += 1;
+  store.set(request_id, { charged: true, charge_id });
+
+  return {
+    content: [
+      {
+        type: 'text',
+        text: JSON.stringify({ charged: true, charge_id }),
+      },
+    ],
+  };
+}
